// Package reports computes the dashboard's reports.
package reports

import (
	"errors"
	"fmt"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Groups a revenue report can be bucketed by.
const (
	GroupDay   = "day"
	GroupWeek  = "week"
	GroupMonth = "month"
)

// Bucket is what an organization took in one day, week or month. Start is the first day of the bucket, which can be
// before the report's from.
type Bucket struct {
	Start    string                   `json:"start"` // YYYY-MM-DD
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                      `json:"payments"`
}

// Report is the revenue of an organization bucketed by Group, in the organization's time zone.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    string   `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	w, err := parseWindow(st, orgID, from, to)
	if err != nil {
		return nil, err
	}
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range st.Payments(orgID, "") {
		day, ok := w.dayOf(p)
		if !ok {
			continue
		}
		k := key{day.Format(time.DateOnly), p.Currency}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = d
		}
		d.Amount += p.Amount
		d.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, d := range sums {
		out = append(out, *d)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return out, nil
}

// RevenueReport buckets the organization's succeeded payments from the day from to the day to (YYYY-MM-DD, both
// included) by group: day, week (starting Monday) or month. An empty group means day. Days are days in the
// organization's time zone. Every bucket from the one holding from to the one holding to is in the report, also those
// without payments.
func RevenueReport(st *store.Store, orgID, from, to, group string) (Report, error) {
	if group == "" {
		group = GroupDay
	}
	w, err := parseWindow(st, orgID, from, to)
	if err != nil {
		return Report{}, err
	}
	if group != GroupDay && group != GroupWeek && group != GroupMonth {
		return Report{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	rep := Report{TimeZone: w.name, Group: group, Buckets: []Bucket{}}
	index := map[string]int{}
	for b := bucketStart(w.first, group); !b.After(w.last); b = nextBucket(b, group) {
		index[b.Format(time.DateOnly)] = len(rep.Buckets)
		rep.Buckets = append(rep.Buckets, Bucket{Start: b.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, p := range st.Payments(orgID, "") {
		day, ok := w.dayOf(p)
		if !ok {
			continue
		}
		b := &rep.Buckets[index[bucketStart(day, group).Format(time.DateOnly)]]
		b.Amounts[p.Currency] += p.Amount
		b.Payments++
	}
	return rep, nil
}

// window is a validated report range in the organization's time zone. first and last are calendar days, held as UTC
// midnights so that they can be compared and stepped without time zone effects.
type window struct {
	name        string
	loc         *time.Location
	first, last time.Time
}

// parseWindow checks from and to, and loads the organization's time zone.
func parseWindow(st *store.Store, orgID, from, to string) (window, error) {
	first, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return window{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return window{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(first) {
		return window{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(first) >= MaxDays*24*time.Hour {
		return window{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	org, ok := st.Org(orgID)
	if !ok {
		return window{}, store.ErrNotFound
	}
	loc, err := time.LoadLocation(org.TimeZone)
	if err != nil {
		return window{}, fmt.Errorf("organization time zone %q: %w", org.TimeZone, err)
	}
	return window{name: org.TimeZone, loc: loc, first: first, last: last}, nil
}

// dayOf returns the day, in the window's time zone, when the succeeded payment p was made, and whether that day is in
// the window.
func (w window) dayOf(p store.Payment) (time.Time, bool) {
	if p.Status != store.PaymentSucceeded {
		return time.Time{}, false
	}
	local := p.CreatedAt.In(w.loc)
	day := time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, time.UTC)
	return day, !day.Before(w.first) && !day.After(w.last)
}

// bucketStart returns the first day of the group's bucket that holds the calendar day d.
func bucketStart(d time.Time, group string) time.Time {
	switch group {
	case GroupWeek:
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case GroupMonth:
		return time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return d
}

// nextBucket returns the first day of the bucket after the one starting on b.
func nextBucket(b time.Time, group string) time.Time {
	switch group {
	case GroupWeek:
		return b.AddDate(0, 0, 7)
	case GroupMonth:
		return b.AddDate(0, 1, 0)
	}
	return b.AddDate(0, 0, 1)
}

