// reportFixture makes an organization in timeZone and returns a function that records a payment made at a given time.
func reportFixture(t *testing.T, timeZone string) (*store.Store, string, func(int64, money.Currency, store.PaymentStatus, time.Time)) {
	t.Helper()
	st := store.New()
	now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	o, err := st.CreateOrg("A", store.OrgTeam, timeZone, 0, now)
	if err != nil {
		t.Fatal(err)
	}
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, now)
	pay := func(amount int64, cur money.Currency, status store.PaymentStatus, at time.Time) {
		if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: amount, Currency: cur, Status: status}, at); err != nil {
			t.Fatal(err)
		}
	}
	return st, o.ID, pay
}

func TestRevenueUsesOrganizationTimeZone(t *testing.T) {
	st, orgID, pay := reportFixture(t, "America/New_York")
	utc := func(d, h, m int) time.Time { return time.Date(2026, 3, d, h, m, 0, 0, time.UTC) }
	pay(1000, money.USD, store.PaymentSucceeded, utc(2, 2, 0))  // 2026-03-01 21:00 EST
	pay(2000, money.USD, store.PaymentSucceeded, utc(9, 3, 30)) // 2026-03-08 23:30 EST, the day that starts daylight saving time
	pay(300, money.USD, store.PaymentSucceeded, utc(9, 3, 59))  // 2026-03-08 23:59 EDT
	pay(500, money.USD, store.PaymentSucceeded, utc(9, 4, 0))   // 2026-03-09 00:00 EDT
	got, err := Revenue(st, orgID, "2026-03-01", "2026-03-09")
	if err != nil {
		t.Fatal(err)
	}
	want := []DayRevenue{
		{Date: "2026-03-01", Currency: money.USD, Amount: 1000, Payments: 1},
		{Date: "2026-03-08", Currency: money.USD, Amount: 2300, Payments: 2},
		{Date: "2026-03-09", Currency: money.USD, Amount: 500, Payments: 1},
	}
	if len(got) != len(want) {
		t.Fatalf("Revenue = %+v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("day %d = %+v, want %+v", i, got[i], want[i])
		}
	}
}

