		}
	}
}

func TestRevenueReportDays(t *testing.T) {
	st, orgID, pay := reportFixture(t, "America/New_York")
	utc := func(d, h, m int) time.Time { return time.Date(2026, 3, d, h, m, 0, 0, time.UTC) }
	pay(1000, money.USD, store.PaymentSucceeded, utc(2, 2, 0))  // 2026-03-01 21:00 EST
	pay(2000, money.USD, store.PaymentSucceeded, utc(9, 3, 30)) // 2026-03-08 23:30 EST
	pay(300, money.USD, store.PaymentSucceeded, utc(9, 3, 59))  // 2026-03-08 23:59 EDT
	pay(500, money.USD, store.PaymentSucceeded, utc(9, 4, 0))   // 2026-03-09 00:00 EDT
	rep, err := RevenueReport(st, orgID, "2026-03-01", "2026-03-09", "")
	if err != nil {
		t.Fatal(err)
	}
	if rep.TimeZone != "America/New_York" || rep.Group != GroupDay || len(rep.Buckets) != 9 {
		t.Fatalf("report = %+v", rep)
	}
	if b := rep.Buckets[0]; b.Start != "2026-03-01" || b.Payments != 1 || b.Amounts[money.USD] != 1000 {
		t.Fatalf("first day = %+v", b)
	}
	if b := rep.Buckets[1]; b.Start != "2026-03-02" || b.Payments != 0 || len(b.Amounts) != 0 {
		t.Fatalf("empty day = %+v", b)
	}
	if b := rep.Buckets[7]; b.Start != "2026-03-08" || b.Payments != 2 || b.Amounts[money.USD] != 2300 {
		t.Fatalf("day of the clock change = %+v", b)
	}
	if b := rep.Buckets[8]; b.Start != "2026-03-09" || b.Payments != 1 || b.Amounts[money.USD] != 500 {
		t.Fatalf("last day = %+v", b)
	}
}

func TestRevenueReportWeeksAndMonths(t *testing.T) {
	st, orgID, pay := reportFixture(t, "UTC")
	day := func(m time.Month, d int) time.Time { return time.Date(2026, m, d, 12, 0, 0, 0, time.UTC) }
	pay(100, money.USD, store.PaymentSucceeded, day(3, 2))  // Monday, before the week of from
	pay(200, money.USD, store.PaymentSucceeded, day(3, 3))  // before from
	pay(50, money.EUR, store.PaymentSucceeded, day(3, 4))   // Wednesday
	pay(300, money.USD, store.PaymentFailed, day(3, 4))     // not succeeded
	pay(400, money.USD, store.PaymentSucceeded, day(3, 10)) // Tuesday of the next week
	pay(500, money.USD, store.PaymentSucceeded, day(4, 2))  // April

	week, err := RevenueReport(st, orgID, "2026-03-04", "2026-03-15", GroupWeek)
	if err != nil {
		t.Fatal(err)
	}
	if len(week.Buckets) != 2 {
		t.Fatalf("weeks = %+v", week)
	}
	if b := week.Buckets[0]; b.Start != "2026-03-02" || b.Payments != 1 || b.Amounts[money.EUR] != 50 || len(b.Amounts) != 1 {
		t.Fatalf("week of from = %+v", b)
	}
	if b := week.Buckets[1]; b.Start != "2026-03-09" || b.Payments != 1 || b.Amounts[money.USD] != 400 {
		t.Fatalf("next week = %+v", b)
	}

	month, err := RevenueReport(st, orgID, "2026-02-15", "2026-04-02", GroupMonth)
	if err != nil {
		t.Fatal(err)
	}
	if len(month.Buckets) != 3 {
		t.Fatalf("months = %+v", month)
	}
	if b := month.Buckets[0]; b.Start != "2026-02-01" || b.Payments != 0 || b.Amounts == nil || len(b.Amounts) != 0 {
		t.Fatalf("empty month = %+v", b)
	}
	if b := month.Buckets[1]; b.Start != "2026-03-01" || b.Payments != 4 || b.Amounts[money.USD] != 700 || b.Amounts[money.EUR] != 50 {
		t.Fatalf("March = %+v", b)
	}
	if b := month.Buckets[2]; b.Start != "2026-04-01" || b.Payments != 1 || b.Amounts[money.USD] != 500 {
		t.Fatalf("April = %+v", b)
	}
}

func TestRevenueReportErrors(t *testing.T) {
	st, orgID, _ := reportFixture(t, "UTC")
	for _, c := range []struct {
		from, to, group string
		want            error
	}{
		{"2026-03-01", "2026-03-05", "year", ErrInvalidGroup},
		{"2026-03-01", "2026-03-05", "Day", ErrInvalidGroup},
		{"", "2026-03-05", "day", ErrInvalidDate},
		{"2026-03-05", "2026-03-01", "week", ErrInvalidRange},
	} {
		if _, err := RevenueReport(st, orgID, c.from, c.to, c.group); !errors.Is(err, c.want) {
			t.Errorf("RevenueReport(%s, %s, %q) = %v, want %v", c.from, c.to, c.group, err, c.want)
		}
	}
}

